 test("Equipment: Flail extends fixed skill range and adds damage",()=>{reset();let h4=make('Kazu'),e4=make('Rodoc',2,4,0);HeroCore.begin(h4,2);HeroCore.selection.cardUid=card('EQUIP_INF_ATK_006',h4).uid;let selected=HeroCore.select(e4);HeroCore.commit();resolveCombat();return JSON.stringify([selected,e4.hp,HeroCore.skillRange(h4,heroSkill(h4,2))])===JSON.stringify([true,0,3])});
