 test("Range recovery: Canceled range gear pauses normal attack and rejects old out-of-range target",()=>JSON.stringify((()=>{reset();let a=make('Est'),d=make('Rodoc',2,2,0),near=troop('INF',2,1,0);let n=card('EQUIP_COMMON_BOTH_002',d);S.selected=a;S.attackChoice={card:card('EQUIP_INF_ATK_004',a)};startAttack(a,d);EquipmentCore.counterEquipment(d,n);let before=[!!HeroCore.selection?.equipmentRecovery,!!S.pending,HeroCore.select(d),a.attacked];HeroCore.select(near);let committed=HeroCore.commit();resolveCombat();return [...before,committed,d.hp,near.hp,S.hands[1].length,duelUsage().attackCard[1]]})())===JSON.stringify([true,false,false,true,true,3,1,0,1]));
