 test("Range recovery: Skipping range recovery spends original Hero skill",()=>JSON.stringify((()=>{reset();let a=make('Kazu'),d=make('Rodoc',2,4,0);let n=card('EQUIP_COMMON_BOTH_002',d);HeroCore.begin(a,2);HeroCore.selection.cardUid=card('EQUIP_INF_ATK_006',a).uid;HeroCore.select(d);HeroCore.commit();EquipmentCore.counterEquipment(d,n);EquipmentCore.skipRecovery();return [isSkillUsed(a,2),a.attacked,d.hp,!!S.heroSequence]})())===JSON.stringify([true,true,3,false]));
