 test("Teleport Ring: Teleport Ring preserves normal movement and does not commit Hero",()=>JSON.stringify((()=>{reset();let h=make('Lucy');h.moved=true;h.movementCostSpent=2;EquipmentCore.begin(h,card('EQUIP_COMMON_BOTH_004',h));let picked=HeroCore.selectCell(cells.find(c=>c.q===4&&c.r===0));HeroCore.commit();return [picked,h.q,h.r,h.moved,h.movementCostSpent,h.attacked,Object.keys(S.skillUsed).length,duelUsage().attackCard[1]]})())===JSON.stringify([true,4,0,true,2,false,0,1]));
 test("Teleport Ring: Teleport Ring rejects troops, dead Heroes and committed Heroes",()=>JSON.stringify((()=>{reset();let h=make('Est'),t=troop('INF',1,1,0);let c=card('EQUIP_COMMON_BOTH_004',h);let troopUse=EquipmentCore.canUse(t,c),troopCard=validCardFor(c,t,'atk');h.attacked=true;let committed=EquipmentCore.canUse(h,c);h.attacked=false;h.hp=0;return [troopUse,troopCard,committed,EquipmentCore.canUse(h,c)]})())===JSON.stringify([false,false,false,false]));
 test("Teleport Ring: Teleport Ring skips intervening units and blocked terrain but rejects bad destination",()=>JSON.stringify((()=>{reset();let h=make('Grim');troop('INF',1,1,0);let block=cells.find(c=>c.q===2&&c.r===0);block.blocked=true;EquipmentCore.begin(h,card('EQUIP_COMMON_BOTH_004',h));let options=[HeroCore.selectCell(cells.find(c=>c.q===0&&c.r===0)),HeroCore.selectCell(cells.find(c=>c.q===1&&c.r===0)),HeroCore.selectCell(block),HeroCore.selectCell(cells.find(c=>c.q===5&&c.r===0)),HeroCore.selectCell(cells.find(c=>c.q===4&&c.r===0))];HeroCore.commit();delete block.blocked;return [...options,h.q,h.hp]})())===JSON.stringify([false,false,false,false,true,4,3]));
 test("Teleport Ring: Teleport Ring cancels damage and stun at sufficient stars during defense",()=>JSON.stringify((()=>{reset();let a=make('Kazu'),h=make('Grim',2,3,0);use(a,2,[h]);let started=EquipmentCore.useDefense(h,card('EQUIP_COMMON_BOTH_004',h));HeroCore.selectCell(cells.find(c=>c.q===3&&c.r===1));HeroCore.commit();return [started,h.q,h.r,h.hp,HeroCore.blocked(h,'defense'),!!S.pending,duelUsage().defenseCard[2],h.moved,h.attacked]})())===JSON.stringify([true,3,1,3,false,false,1,false,false]));
 test("Teleport Ring: Teleport Ring cannot evade an attack over three stars",()=>JSON.stringify((()=>{reset();let a=make('Mask'),h=make('Grim',2,3,0);use(a,3,[h]);let c=card('EQUIP_COMMON_BOTH_004',h);return [EquipmentCore.useDefense(h,c),h.q,S.hands[2].length,!!S.pending]})())===JSON.stringify([false,3,1,true]));
 test("Teleport Ring: Teleport Ring in defense requires its Hero to be receiving the hit",()=>JSON.stringify((()=>{reset();let a=make('Est'),h=make('Grim',2,3,0),d=make('Lucy',2,1,0);let c=card('EQUIP_COMMON_BOTH_004',h);let idle=EquipmentCore.canUse(h,c);S.selected=a;startAttack(a,d);return [idle,EquipmentCore.canUse(h,c),EquipmentCore.canUse(d,c)]})())===JSON.stringify([false,false,true]));
 test("Teleport Ring: Teleport Ring canceled by Necklace does not move or evade Hero",()=>JSON.stringify((()=>{reset();let a=make('Kazu'),h=make('Grim',2,3,0);let n=card('EQUIP_COMMON_BOTH_002',a);use(a,2,[h]);EquipmentCore.useDefense(h,card('EQUIP_COMMON_BOTH_004',h));HeroCore.selectCell(cells.find(c=>c.q===3&&c.r===1));HeroCore.commit();EquipmentCore.counterEquipment(a,n);let before=[h.q,h.r,S.pending.cancel===false];resolveCombat();return [...before,h.hp,HeroCore.blocked(h,'defense'),S.hands[2].length,duelUsage().defenseCard[2]]})())===JSON.stringify([3,0,true,1,true,0,1]));
 test("Teleport Ring: Canceling Teleport Ring targeting retains card and budget",()=>JSON.stringify((()=>{reset();let h=make('Ranus');EquipmentCore.begin(h,card('EQUIP_COMMON_BOTH_004',h));HeroCore.selectCell(cells.find(c=>c.q===4&&c.r===0));HeroCore.cancel();return [h.q,S.hands[1].length,duelUsage().attackCard[1],!!HeroCore.selection]})())===JSON.stringify([0,1,0,false]));
 test("Teleport Ring: Teleport Ring cannot replace its payment with another equipment card",()=>JSON.stringify((()=>{reset();let a=make('Est'),h=make('Lucy',2,1,0);S.selected=a;startAttack(a,h);EquipmentCore.useDefense(h,card('EQUIP_COMMON_BOTH_004',h));HeroCore.selectCell(cells.find(c=>c.q===2&&c.r===0));HeroCore.selection.cardUid=card('EQUIP_ARCH_DEF_001',h).uid;return [HeroCore.commit(),h.q,S.hands[2].length]})())===JSON.stringify([false,1,2]));
 test("Teleport Ring: Teleport Ring is unavailable when every destination is blocked",()=>JSON.stringify((()=>{reset();let h=make('Est'),c=card('EQUIP_COMMON_BOTH_004',h);let nearby=cells.filter(x=>distU(h,x)>0&&distU(h,x)<=4);for(const x of nearby)x.blocked=true;let allowed=EquipmentCore.begin(h,c);for(const x of nearby)delete x.blocked;return [allowed,h.q,S.hands[1].length,duelUsage().attackCard[1]]})())===JSON.stringify([false,0,1,0]));
